<script setup>
import { ref, reactive } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useAuth } from '../stores/auth'
import { errorMessage, fieldErrors } from '../services/api'
import PageHeading from '../components/PageHeading.vue'
const auth=useAuth(), route=useRoute(), router=useRouter(), busy=ref(false), show=ref(false), error=ref(route.query.error?'No se pudo verificar la sesión. Compruebe su conexión.':''), errors=ref({}), form=reactive({email:'',password:''})
async function submit() { busy.value=true; error.value=''; errors.value={}; try { await auth.login(form); const target=route.query.redirect; router.replace(typeof target==='string'&&target.startsWith('/')&&!target.startsWith('//')&&!target.startsWith('/login')?target:auth.canDeposit?'/depositos':auth.canReview?'/revision':'/') } catch(e) { error.value=errorMessage(e); errors.value=fieldErrors(e) } finally { busy.value=false } }
</script>
<template><PageHeading title="Iniciar sesión" subtitle="Acceda con su cuenta para gestionar depósitos y utilizar las funciones de su rol." /><section class="surface login-panel"><h2>Bienvenido al repositorio</h2><p class="muted">Ingrese sus credenciales institucionales.</p><p v-if="error" class="alert" role="alert">{{ error }}</p><q-form @submit="submit"><q-input v-model="form.email" label="Correo electrónico *" outlined type="email" autocomplete="username" :rules="[v=>!!v||'Ingrese su correo electrónico']" :error="!!errors.email" :error-message="errors.email" /><q-input v-model="form.password" label="Contraseña *" outlined :type="show?'text':'password'" autocomplete="current-password" :rules="[v=>!!v||'Ingrese su contraseña']" :error="!!errors.password" :error-message="errors.password"><template #append><q-btn flat round dense :icon="show?'visibility_off':'visibility'" :aria-label="show?'Ocultar contraseña':'Mostrar contraseña'" @click="show=!show" /></template></q-input><q-btn unelevated color="primary" label="Iniciar sesión" type="submit" class="full-width" :loading="busy" /></q-form><p class="muted q-mt-lg q-mb-none">¿Necesita una cuenta o recuperar su acceso? Contacte al administrador del repositorio.</p><q-btn flat color="primary" to="/" label="Volver a la consulta pública" class="q-mt-md" /></section></template>
